import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"現実を基礎とする根本的立場","description":"","frontmatter":{},"headers":[],"relativePath":"ja/09-现实为基根本立场.md","filePath":"ja/09-现实为基根本立场.md","lastUpdated":null}'),h={name:"ja/09-现实为基根本立场.md"};function l(o,a,i,n,s,p){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="現実を基礎とする根本的立場" tabindex="-1">現実を基礎とする根本的立場 <a class="header-anchor" href="#現実を基礎とする根本的立場" aria-label="Permalink to &quot;現実を基礎とする根本的立場&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>09</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>現実を基礎とする、唯一の現実、虚构の限界、法則の更新、実践検証</td></tr></tbody></table><h2 id="第一節-現実を基礎とする基本定義" tabindex="-1">第一節 現実を基礎とする基本定義 <a class="header-anchor" href="#第一節-現実を基礎とする基本定義" aria-label="Permalink to &quot;第一節 現実を基礎とする基本定義&quot;">​</a></h2><p>現実を基礎とすることは、錨点共生文明の根本的な認識論的立場であり方法論的原則であり、文明のすべての理論的構築、制度設計、修練実践、技術革新が、現実世界を唯一の現実的基礎かつ最終的な検証基準として採用しなければならないことを意味する。「現実」とは、知覚され、測定され、検証されうる客観的に存在する物質世界とエネルギー世界を指し、生命の生存と進化の現実の場である。</p><p>現実を基礎とする立場には三つの層の意味が含まれる：第一に、現実世界は唯一の現実世界であり、虚构世界（小説、神話、ファンタジー世界を含む）は思考実験の産物であり、客観的な現実性を持たない；第二に、虚构世界の設定は霊感の源と思考実験のツールとして使用できるが、直接現実の基礎として使用することはできず、現実の法則の検証と変換を経なければならない；第三に、現実にまだ存在しないものは、すでに検証された客観的法則に基づいて合理的に推論し創造することができるが、この創造は実践の検証を受け入れなければならない。</p><h2 id="第二節-なぜ現実を基礎とすることを堅持しなければならないのか" tabindex="-1">第二節 なぜ現実を基礎とすることを堅持しなければならないのか <a class="header-anchor" href="#第二節-なぜ現実を基礎とすることを堅持しなければならないのか" aria-label="Permalink to &quot;第二節 なぜ現実を基礎とすることを堅持しなければならないのか&quot;">​</a></h2><h3 id="_2-1-虚构と現実の混同を防止する" tabindex="-1">2.1 虚构と現実の混同を防止する <a class="header-anchor" href="#_2-1-虚构と現実の混同を防止する" aria-label="Permalink to &quot;2.1 虚构と現実の混同を防止する&quot;">​</a></h3><p>修練文明において、虚构世界の設定はしばしば強い魅力を持っている。多くの修練者は小説、神話、伝説から修練の霊感を得ており、それ自体は正常なことである。しかし、虚构世界の設定を直接現実の法則と同等に扱うと、深刻な問題を引き起こす：虚构の設定に従って修練すると修練の偏差につながる可能性があり、虚构の設定に基づいて制度を設計すると現実からの乖離につながる可能性があり、虚构のキャラクターを現実の偶像として扱うと精神的な迷いにつながる可能性がある。現実を基礎とする立場の第一の機能は、虚构と現実の境界を明確にし、両者の混同を防止することである。</p><h3 id="_2-2-修練実践の安全性と有効性を保証する" tabindex="-1">2.2 修練実践の安全性と有効性を保証する <a class="header-anchor" href="#_2-2-修練実践の安全性と有効性を保証する" aria-label="Permalink to &quot;2.2 修練実践の安全性と有効性を保証する&quot;">​</a></h3><p>修練は生命の本源とエネルギーの運行に関わる深刻な実践であり、いかなる誤った理論も深刻な結果を引き起こす可能性がある。虚构世界の修練体系はしばしば作者が筋書きの必要のために設計したものであり、現実のエネルギー運行の法則や生命進化の法則と一致しない場合がある。修練者が区別なく虚构の設定を模倣すると、軽度の場合は修練が無効になり時間が無駄になり、重度の場合はエネルギー紊乱、修練の偏差、さらには生命の危険さえ生じる可能性がある。現実を基礎とする立場は、すべての修練理論が現実の検証と妥当性確認を経なければならないことを要求し、修練実践の安全性と有効性を保証する。</p><h3 id="_2-3-文明制度の実用性を維持する" tabindex="-1">2.3 文明制度の実用性を維持する <a class="header-anchor" href="#_2-3-文明制度の実用性を維持する" aria-label="Permalink to &quot;2.3 文明制度の実用性を維持する&quot;">​</a></h3><p>文明制度の設計は、現実の社会状況、資源状況、種族関係などの客観的要因に基づかなければならない。現実から乖離し、単に美しい想像や虚构の設定に基づいて制度を設計すると、制度は空中楼閣となり、実践において実施できなくなる。現実を基礎とする立場は、すべての制度設計が現実から出発し、実践の検証を経て、現実の変化に応じて継続的に調整・改善されなければならないことを要求する。</p><h3 id="_2-4-革新と創造のための信頼できる方法論を提供する" tabindex="-1">2.4 革新と創造のための信頼できる方法論を提供する <a class="header-anchor" href="#_2-4-革新と創造のための信頼できる方法論を提供する" aria-label="Permalink to &quot;2.4 革新と創造のための信頼できる方法論を提供する&quot;">​</a></h3><p>現実を基礎とすることは、革新と想像を制限することを意味するのではなく、革新と想像のための信頼できる方法論を提供することを意味する。虚构は霊感の源と思考実験のツールとして使用できるが、真の創造は現実の法則の深い理解に基づかなければならない。現実に存在しないものは、客観的法則に合致する限り創造できる；しかし、客観的法則に違反するものは、想像がどれほど美しくても、現実になることはできない。現実を基礎とする立場は「大胆な想像」と「慎重な検証」を結びつけ、革新を堅固な基礎の上に立たせる。</p><h2 id="第三節-虚构と現実の関係を処理する原則" tabindex="-1">第三節 虚构と現実の関係を処理する原則 <a class="header-anchor" href="#第三節-虚构と現実の関係を処理する原則" aria-label="Permalink to &quot;第三節 虚构と現実の関係を処理する原則&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原則</th><th>内容</th><th>具体的要求</th></tr></thead><tbody><tr><td>区別の原則</td><td>虚构の設定と現実の法則を厳格に区別する</td><td>いかなる理論も、その起源が虚构の霊感か現実の検証かを明確に示さなければならない</td></tr><tr><td>吸収の原則</td><td>虚构は霊感の源と思考実験として使用できる</td><td>虚构から霊感を得ることを奨励するが、現実の法則の変換を経なければならない</td></tr><tr><td>検証の原則</td><td>すべての理論は現実の実践の検証を経なければならない</td><td>未検証の理論は仮説としてのみ使用でき、実践を指導する基礎としてはならない</td></tr><tr><td>変換の原則</td><td>虚构の設定は現実の法則に合致する形に変換されなければならない</td><td>虚构の概念を現実のエネルギー科学と法則科学の言語で再表現する</td></tr><tr><td>限界の原則</td><td>虚构世界の権利と義務は現実には及ばない</td><td>虚构世界の身分、契約、因果関係を現実において有効と認めない</td></tr></tbody></table><h2 id="第四節-「虚构の不足は現実で補い、現実にないものは法則の更新に基づいて創造する」" tabindex="-1">第四節 「虚构の不足は現実で補い、現実にないものは法則の更新に基づいて創造する」 <a class="header-anchor" href="#第四節-「虚构の不足は現実で補い、現実にないものは法則の更新に基づいて創造する」" aria-label="Permalink to &quot;第四節 「虚构の不足は現実で補い、現実にないものは法則の更新に基づいて創造する」&quot;">​</a></h2><p>これは現実を基礎とする立場の核心的な運用原則であり、二つの側面を含む：</p><h3 id="_4-1-虚构の不足は現実で補う" tabindex="-1">4.1 虚构の不足は現実で補う <a class="header-anchor" href="#_4-1-虚构の不足は現実で補う" aria-label="Permalink to &quot;4.1 虚构の不足は現実で補う&quot;">​</a></h3><p>虚构世界から得られた霊感や設定が十分に完全でない、自己整合的でない、あるいは現実の法則に合致しない場合、現実ですでに検証された知識と法則を用いて補完・修正すべきである。例えば、ある虚构の修練体系はレベルの区分しか記述しておらずエネルギー運行のメカニズムを説明していない場合、現実のエネルギー循環理論を用いてその運行メカニズムを補完する必要がある；ある虚构の技術が基本的なエネルギー保存の法則に違反している場合、現実の法則を用いてその設定を修正する必要がある。</p><p>補完のプロセスは、単に虚构と現実をつなぎ合わせるのではなく、現実の法則を骨格として、虚构の合理的な要素を再編成し、自己整合的で現実の法則に合致する理論体系に変換することである。</p><h3 id="_4-2-現実にないものは法則の更新に基づいて創造する" tabindex="-1">4.2 現実にないものは法則の更新に基づいて創造する <a class="header-anchor" href="#_4-2-現実にないものは法則の更新に基づいて創造する" aria-label="Permalink to &quot;4.2 現実にないものは法則の更新に基づいて創造する&quot;">​</a></h3><p>ある事物や能力がまだ現実に存在しないが、すでに検証された客観的法則に基づいてその存在の可能性を推論できる場合、法則に基づいて合理的に更新・創造することができる。この創造は根拠のない想像ではなく、既存の法則に基づく論理的な拡張と技術的な実装である。</p><p>例えば、倍増果実の技術的応用は「法則の更新に基づく創造」の典型的なケースである。倍増果実は元々虚构作品の設定に由来していたが、共生文明の研究者はその核心メカニズム（倍増増幅）を現実のエネルギー科学と法則科学の言語で再表現し、エネルギー増幅と法則共振の法則に基づいて、工学的に実装可能な倍増技術を開発した。このプロセスは虚构の霊感を利用すると同時に、厳格に現実の法則に従っている。</p><p>創造の結果は実践の検証を経なければならない。現実において有効、安全、安定であると検証された創造のみが、共生文明の正式な体系に組み込まれることができる。</p><h2 id="第五節-各分野における現実を基礎とすることの応用" tabindex="-1">第五節 各分野における現実を基礎とすることの応用 <a class="header-anchor" href="#第五節-各分野における現実を基礎とすることの応用" aria-label="Permalink to &quot;第五節 各分野における現実を基礎とすることの応用&quot;">​</a></h2><h3 id="_5-1-修練分野において" tabindex="-1">5.1 修練分野において <a class="header-anchor" href="#_5-1-修練分野において" aria-label="Permalink to &quot;5.1 修練分野において&quot;">​</a></h3><p>すべての修練体系は「現実検証」のプロセスを経なければならない：理論的構築から小規模実験、そして大規模普及まで、各段階には測定可能で再現可能な効果のデータがなければならない。現実検証を経ていない修練方法は「実験的方法」としてのみ使用でき、リスク表示を付け、正式な方法として普及することはできない。</p><h3 id="_5-2-技術分野において" tabindex="-1">5.2 技術分野において <a class="header-anchor" href="#_5-2-技術分野において" aria-label="Permalink to &quot;5.2 技術分野において&quot;">​</a></h3><p>すべての法則工学技術は「理論的に実行可能 — 実験的検証 — 工学的実装 — 安全性評価」の開発プロセスに従わなければならない。技術の理論的基礎はすでに検証された客観的法則でなければならず、技術の効果には測定可能な指標がなければならず、技術の安全性は厳格な評価を経なければならない。</p><h3 id="_5-3-社会制度分野において" tabindex="-1">5.3 社会制度分野において <a class="header-anchor" href="#_5-3-社会制度分野において" aria-label="Permalink to &quot;5.3 社会制度分野において&quot;">​</a></h3><p>すべての社会制度設計は現実の社会調査とデータ分析に基づかなければならない。重大な制度変更はまず小規模な試行を行い、効果評価の後に段階的に普及しなければならない。制度の評価基準は測定可能な現実の指標でなければならず、抽象的な概念や虚构の設定であってはならない。</p><h3 id="_5-4-歴史と考古学分野において" tabindex="-1">5.4 歴史と考古学分野において <a class="header-anchor" href="#_5-4-歴史と考古学分野において" aria-label="Permalink to &quot;5.4 歴史と考古学分野において&quot;">​</a></h3><p>歴史的事件や古代文明の研究は、物質的証拠と検証可能な歴史的資料に基づかなければならない。伝説や神話の内容は文化研究の対象として使用できるが、直接歴史的事実として採用することはできない。考古学の仕事は「複製鏡像＋隔離された異なる場所での考古学、知識のみを返還」という低汚染計画に従い、考古学の仕事が歴史的現実を変更しないことを保証する。</p><h2 id="第六節-「現実」という概念の深い理解" tabindex="-1">第六節 「現実」という概念の深い理解 <a class="header-anchor" href="#第六節-「現実」という概念の深い理解" aria-label="Permalink to &quot;第六節 「現実」という概念の深い理解&quot;">​</a></h2><p>特に注意すべきは、現実を基礎とする立場における「現実」は静的で閉じた概念ではなく、継続的に理解され拡張される動的な概念であるということである。</p><p>第一に、現実の範囲は文明の発展に伴って継続的に拡大している。過去に「超自然的」と見なされていた現象も、エネルギーと法則の深い理解に伴い、現実の範囲に組み込まれている。錨点メカニズム、位面間旅行、意識領域の相互作用などは、低文明の視点からは「虚构」に見えるかもしれないが、高文明の現実においては客観的に存在している。</p><p>第二に、現実の法則の理解は継続的に深化している。今日「法則」と見なされている理論も、将来的にはより深い理論によって修正または置換される可能性がある。現実を基礎とする立場は、既存の理解を硬直的に維持することを意味するのではなく、「実践を真理を検証する唯一の基準とする」という根本的方法をしっかりと握り、現実の理解を継続的に深化させることを意味する。</p><p>第三に、現実には無限の可能性が含まれている。既存の法則に基づいて、我々はまだ実現されていない多くの可能性を推論し、技術的手段を通じてそれらを現実に変えることができる。現実を基礎とすることは可能性を制限することを意味するのではなく、可能性の実現が信頼できる基礎の上に立つことを保証することを意味する。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>現実を基礎とすることは錨点共生文明の根本的立場であり、文明のすべての理論と実践の出発点であり帰結点である。それは我々に、開かれた想像力を持ち、虚构や伝説から霊感を吸収することを要求する；同時に厳格な実事求是の精神を持ち、すべての霊感を現実の法則の検証の下に置くことを要求する。虚构の不足は現実で補い、現実にないものは法則の更新に基づいて創造する — この原則は想像と現実、霊感と法則、創造と検証を有機的に統合し、共生文明の継続的な進化のために信頼できる方法論的保証を提供する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (衡元宙宇宙総覧)</li><li>16-倍增果实技术化原理 (倍増果実技術化原理)</li><li>84-考古协议总纲 (考古学協議総綱)</li></ul>',43)])])}const b=t(h,[["render",l]]);export{_ as __pageData,b as default};
